INSERT INTO public.english_sas_questions (code, subject, topic_slug, topic_name, difficulty, cognitive_level, stimulus_type, stimulus_content, question_text, options, correct_answer, hint, explanation, tags)
VALUES
  ('ENG10-RD-001', 'Bahasa Inggris Kelas X', 'reading-narrative-recount', 'Reading: Narrative, Mystery, Historical & Recount', 'mudah', 'C2', 'text', 'The Legend of Lake Toba

Long ago, a young farmer named Toba lived alone in a quiet valley in North Sumatra. One afternoon, he went fishing in the river and caught a magnificent golden fish. To his amazement, when he brought it home, the fish transformed into a beautiful woman. She agreed to marry him under one strict condition: Toba must never tell anyone that she was once a fish. Toba promised to keep the secret forever.

Years passed, and they had a lively son named Samosir. However, Samosir grew up to be quite lazy and always felt hungry. One hot afternoon, his mother asked him to deliver lunch to his father in the rice field. On the way, Samosir got hungry and ate almost all the food, leaving only a few scraps.

When Toba opened the lunch basket and saw the leftovers, he lost his temper. He shouted furiously at his son, "You careless boy! You act just like the child of a fish!" Samosir cried and ran home to tell his mother what his father had said. Heartbroken that Toba had broken his sacred promise, the woman told Samosir to run to the highest hill immediately. Suddenly, dark clouds covered the sky, and heavy rain fell non-stop. Water overflowed from the river, flooding the entire valley and turning it into a vast lake, with the hill remaining as an island in the center.', 'Why did Toba become furious at his son in the rice field?', '[{"key":"A","text":"Samosir refused to help him plant the rice seeds."},{"key":"B","text":"Samosir arrived late because he fell asleep on the hill."},{"key":"C","text":"Samosir lost the lunch basket inside the deep river."},{"key":"D","text":"Samosir told the villagers about his mother''s secret."},{"key":"E","text":"Samosir ate almost all of the lunch meant for him."}]'::jsonb, 'E', 'Read the end of the second paragraph carefully to see what happened on the way to the rice field.', 'The second paragraph states: "On the way, Samosir got hungry and ate almost all the food, leaving only a few scraps." Seeing the leftovers made Toba lose his temper.', ARRAY['narrative', 'reading-comprehension', 'lake-toba']::text[]),
  ('ENG10-RD-002', 'Bahasa Inggris Kelas X', 'reading-narrative-recount', 'Reading: Narrative, Mystery, Historical & Recount', 'mudah', 'C2', 'text', 'The Legend of Lake Toba

Long ago, a young farmer named Toba lived alone in a quiet valley in North Sumatra. One afternoon, he went fishing in the river and caught a magnificent golden fish. To his amazement, when he brought it home, the fish transformed into a beautiful woman. She agreed to marry him under one strict condition: Toba must never tell anyone that she was once a fish. Toba promised to keep the secret forever.

Years passed, and they had a lively son named Samosir. However, Samosir grew up to be quite lazy and always felt hungry. One hot afternoon, his mother asked him to deliver lunch to his father in the rice field. On the way, Samosir got hungry and ate almost all the food, leaving only a few scraps.

When Toba opened the lunch basket and saw the leftovers, he lost his temper. He shouted furiously at his son, "You careless boy! You act just like the child of a fish!" Samosir cried and ran home to tell his mother what his father had said. Heartbroken that Toba had broken his sacred promise, the woman told Samosir to run to the highest hill immediately. Suddenly, dark clouds covered the sky, and heavy rain fell non-stop. Water overflowed from the river, flooding the entire valley and turning it into a vast lake, with the hill remaining as an island in the center.', 'What was the main cause of the valley flooding into a giant lake?', '[{"key":"A","text":"A powerful earthquake shook the mountains of North Sumatra."},{"key":"B","text":"Toba broke his promise by revealing his wife''s true origin."},{"key":"C","text":"The golden fish returned to the river to summon a terrible storm."},{"key":"D","text":"The villagers forgot to build barriers before the rainy season."},{"key":"E","text":"Samosir accidentally blocked the main river with large stones."}]'::jsonb, 'B', 'Focus on the strict condition given at the start and Toba’s shout in the third paragraph.', 'When Toba yelled "You act just like the child of a fish!", he violated his sacred vow never to reveal her fish origin, triggering the relentless storm that flooded the valley.', ARRAY['narrative', 'cause-effect', 'lake-toba']::text[]),
  ('ENG10-RD-003', 'Bahasa Inggris Kelas X', 'reading-narrative-recount', 'Reading: Narrative, Mystery, Historical & Recount', 'mudah', 'C1', 'text', 'The Legend of Lake Toba

Long ago, a young farmer named Toba lived alone in a quiet valley in North Sumatra. One afternoon, he went fishing in the river and caught a magnificent golden fish. To his amazement, when he brought it home, the fish transformed into a beautiful woman. She agreed to marry him under one strict condition: Toba must never tell anyone that she was once a fish. Toba promised to keep the secret forever.

Years passed, and they had a lively son named Samosir. However, Samosir grew up to be quite lazy and always felt hungry. One hot afternoon, his mother asked him to deliver lunch to his father in the rice field. On the way, Samosir got hungry and ate almost all the food, leaving only a few scraps.

When Toba opened the lunch basket and saw the leftovers, he lost his temper. He shouted furiously at his son, "You careless boy! You act just like the child of a fish!" Samosir cried and ran home to tell his mother what his father had said. Heartbroken that Toba had broken his sacred promise, the woman told Samosir to run to the highest hill immediately. Suddenly, dark clouds covered the sky, and heavy rain fell non-stop. Water overflowed from the river, flooding the entire valley and turning it into a vast lake, with the hill remaining as an island in the center.', 'The synonym of the word "furiously" in the phrase "He shouted furiously at his son" is ….', '[{"key":"A","text":"angrily"},{"key":"B","text":"patiently"},{"key":"C","text":"cheerfully"},{"key":"D","text":"silently"},{"key":"E","text":"nervously"}]'::jsonb, 'A', 'Notice the sentence right before it says "he lost his temper."', '"Furiously" means in an extremely angry manner, which matches "angrily."', ARRAY['vocabulary', 'synonym', 'lake-toba']::text[]),
  ('ENG10-RD-004', 'Bahasa Inggris Kelas X', 'reading-narrative-recount', 'Reading: Narrative, Mystery, Historical & Recount', 'medium', 'C3', 'text', 'The Legend of Lake Toba

Long ago, a young farmer named Toba lived alone in a quiet valley in North Sumatra. One afternoon, he went fishing in the river and caught a magnificent golden fish. To his amazement, when he brought it home, the fish transformed into a beautiful woman. She agreed to marry him under one strict condition: Toba must never tell anyone that she was once a fish. Toba promised to keep the secret forever.

Years passed, and they had a lively son named Samosir. However, Samosir grew up to be quite lazy and always felt hungry. One hot afternoon, his mother asked him to deliver lunch to his father in the rice field. On the way, Samosir got hungry and ate almost all the food, leaving only a few scraps.

When Toba opened the lunch basket and saw the leftovers, he lost his temper. He shouted furiously at his son, "You careless boy! You act just like the child of a fish!" Samosir cried and ran home to tell his mother what his father had said. Heartbroken that Toba had broken his sacred promise, the woman told Samosir to run to the highest hill immediately. Suddenly, dark clouds covered the sky, and heavy rain fell non-stop. Water overflowed from the river, flooding the entire valley and turning it into a vast lake, with the hill remaining as an island in the center.', 'Why did the mother instruct Samosir to climb to the highest hill right after learning what Toba had said?', '[{"key":"A","text":"She asked Samosir to search for fresh rice seedlings for his father."},{"key":"B","text":"She wanted Samosir to stay safe above the valley before a massive flood submerged the area."},{"key":"C","text":"She wanted Samosir to hide the empty lunch basket from the neighbors."},{"key":"D","text":"She wanted Samosir to catch more golden fish from a highland spring."},{"key":"E","text":"She expected Samosir to apologize to his father from the hilltop."}]'::jsonb, 'B', 'Look at what happened immediately after Samosir ran to the highest hill.', 'Non-stop rain flooded the valley and turned it into a vast lake while leaving the hill as an island in the center, saving Samosir from drowning.', ARRAY['narrative', 'inference', 'lake-toba']::text[]),
  ('ENG10-RD-005', 'Bahasa Inggris Kelas X', 'reading-narrative-recount', 'Reading: Narrative, Mystery, Historical & Recount', 'mudah', 'C2', 'text', 'The Mystery of the Missing Painting

Late one rainy evening, Detective Clara Vance was called to the Blackwood Art Museum. The curator, Mr. Sterling, looked pale and anxious. "Detective, our most valuable 18th-century painting, The Crimson Rose, has vanished from the main gallery!" he exclaimed. "The security cameras were turned off at 9:00 PM, and all the doors were locked from the inside."

Clara walked into the silent gallery with her assistant, Leo. She ignored the empty frame on the wall and immediately inspected the polished marble floor. "Look at these faint muddy footprints leading toward the ventilation shaft," Clara pointed out. "And notice that the window latch is completely dry, even though it has been pouring outside since dusk."

Clara turned to the museum staff standing near the entrance. "The thief did not break in from outside," she announced calmly. "Whoever took the painting was already inside the building before the rain started, and they used the maintenance shaft to hide the canvas." She walked straight to the janitor''s closet, opened the metal vent cover, and pulled out the rolled-up painting. Mr. Sterling''s assistant, who had muddy boots hidden under his desk, immediately confessed to the crime.', 'What did Detective Clara discover when she examined the gallery floor?', '[{"key":"A","text":"Broken glass scattered beneath the main gallery window."},{"key":"B","text":"A torn piece of canvas stuck inside the empty wooden frame."},{"key":"C","text":"A spare key dropped near the security camera control room."},{"key":"D","text":"Wet drops of rainwater trailing from the front entrance door."},{"key":"E","text":"Faint muddy footprints leading toward the ventilation shaft."}]'::jsonb, 'E', 'Check what Clara pointed out on the polished marble floor in the second paragraph.', 'In paragraph 2, Clara inspected the polished marble floor and said, "Look at these faint muddy footprints leading toward the ventilation shaft."', ARRAY['narrative', 'mystery', 'detail']::text[]),
  ('ENG10-RD-006', 'Bahasa Inggris Kelas X', 'reading-narrative-recount', 'Reading: Narrative, Mystery, Historical & Recount', 'medium', 'C4', 'text', 'The Mystery of the Missing Painting

Late one rainy evening, Detective Clara Vance was called to the Blackwood Art Museum. The curator, Mr. Sterling, looked pale and anxious. "Detective, our most valuable 18th-century painting, The Crimson Rose, has vanished from the main gallery!" he exclaimed. "The security cameras were turned off at 9:00 PM, and all the doors were locked from the inside."

Clara walked into the silent gallery with her assistant, Leo. She ignored the empty frame on the wall and immediately inspected the polished marble floor. "Look at these faint muddy footprints leading toward the ventilation shaft," Clara pointed out. "And notice that the window latch is completely dry, even though it has been pouring outside since dusk."

Clara turned to the museum staff standing near the entrance. "The thief did not break in from outside," she announced calmly. "Whoever took the painting was already inside the building before the rain started, and they used the maintenance shaft to hide the canvas." She walked straight to the janitor''s closet, opened the metal vent cover, and pulled out the rolled-up painting. Mr. Sterling''s assistant, who had muddy boots hidden under his desk, immediately confessed to the crime.', 'How did Clara deduce that the thief was an insider rather than an external burglar?', '[{"key":"A","text":"The window latch was dry despite the heavy rain outside."},{"key":"B","text":"The security cameras recorded the assistant entering the closet."},{"key":"C","text":"The front doors had been unlocked using the curator''s personal key."},{"key":"D","text":"The muddy footprints matched the exact size of Mr. Sterling''s shoes."},{"key":"E","text":"The thief left a written confession inside the maintenance shaft."}]'::jsonb, 'A', 'Look at the contrast Clara noticed between the weather outside and the state of the window latch.', 'Because the window latch was completely dry even though it had been pouring since dusk (and all doors were locked from inside), nobody entered from outdoors.', ARRAY['narrative', 'mystery', 'deduction']::text[]),
  ('ENG10-RD-007', 'Bahasa Inggris Kelas X', 'reading-narrative-recount', 'Reading: Narrative, Mystery, Historical & Recount', 'medium', 'C3', 'text', 'The Mystery of the Missing Painting

